INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('b15ed334-92c7-4738-a3bf-9f559ccaea47', 'Common Area Maintenance Charges', '13', '8', 'RENTA Y FORMA DE PAGO', E'- The subtenant agrees to pay the sublandlord a monthly rent of $305,760.00 MXN.\n- This amount includes the applicable Value Added Tax (VAT).\n- The rent also covers the maintenance fee for the shopping center.', 'LA SUBARRENDATARIA se obliga a pagar a EL SUBARRENDADOR por concepto de renta, la cantidad de $305,760.00 (Trescientos cinco mil setecientos sesenta pesos 00/100 M.N.), más el Impuesto al Valor Agregado correspondiente (en lo sucesivo la "RENTA MENSUAL"), misma que incluye la cuota de mantenimiento del Centro Comercial.');
INSERT INTO locations (id, nombre, brand_id, company_id, address1, address2, city, state, zip, country, full_address, latitude, longitude, location_type, location_subtype, business_category, business_type, property_name, square_meters, total_leased_sqm, total_subleased_sqm, atributos_extra) VALUES ('2178a0ef-32f6-4f9f-b6db-f3ed3d2ca4d2', 'Plaza Torrecillas', '43a59b98-494b-4f44-a59a-ad5bb1b79127', '83602737-ca9f-417e-b1ac-19d0ad371be6', '555 Municipio Libre Y Nayarit', 'Subancla D', 'El Jardín, Puebla', 'Puebla', '72490', 'MX', '555 Municipio Libre Y Nayarit, Subancla D, El Jardín, Puebla, Puebla 72490', 18.9997579857, -98.2301465787, 'Retail', 'Lifestyle Center', 'Sports & Recreation', 'Franchise', 'Centro Comercial Soriana Torrecillas', 2482, 2482, NULL, '{"map_lease_expiration_date":"2032-04-07","map_marker_color":"#A879D2","coordinate":"point|18.9997579857|-98.2301465787|accurate","city_state":"El Jardín, Puebla, Puebla","company_name":"Fitness Para Todos, S. de R.L. de C.V.","location_currency":{"id":"mexican_peso","label":"Mexican peso","symbol":"$","code":"MXN","default":false},"landlord_company_full_address":"3102 Avenida Alejandro De Rodas, A, Monterrey, MX-NLE 64610","tenant_company_full_address":"Calzada De Los Leones 170 Piso 1, Alvaro Obregon, CDMX 01010","tenant_company_addr1":"Calzada De Los Leones 170 Piso 1","tenant_company_city":"Alvaro Obregon","tenant_company_state":"CDMX","tenant_company_zip":"01010","tenant_company_country":"MX","lease_currency":{"id":"mexican_peso","label":"Mexican peso","symbol":"$","code":"MXN","default":false},"next_option_expiration_date":"2037-04-07","lease_expiration_date":"2032-04-07","lease_renewal_notice":"60 Days Prior","lease_length_in_months_remaining":66,"lease_most_recent_note":"No","see_lease_for_details":"No","lease_is_silent":"No","rtr_enabled":1,"grid_id":57822,"grid_name":"Plaza Torrecillas","grid_full_address":"555 Municipio Libre Y Nayarit, Subancla D, El Jardín, Puebla, Puebla 72490","map_addr_1":"555 Municipio Libre Y Nayarit","map_addr_2":"Subancla D","map_city_state_zip":"El Jardín, Puebla, Puebla 72490","grid_brand":"Planet Fitness","location_created_at":"2025-09-29 16:43:14","active_lease_count_over_time":51132,"location_count_over_time":57822,"remaining_rent_liability_over_time":51132}'::jsonb);
INSERT INTO leases (id, location_id, tenant_company_id, lease_name, lease_type, is_sub_lease, estatus, acquisition_type, lease_classification, rent_commencement_date, delivery_date, expiration_date, expiration_date_including_options, is_month_to_month, number_of_options, each_option_years, remaining_options, remaining_options_years, renewal_notice_period_start, renewal_notice_deadline, renewal_notice_intention, length_of_lease_months, landlord_nombre, landlord_parent_company, landlord_vendor_id, landlord_address1, landlord_address2, landlord_city, landlord_state, landlord_zip, landlord_country, landlord_poc_nombre, landlord_poc_telefono, landlord_poc_email, grace_period_dias, late_fee_type, late_fee_monto, security_deposit, rental_prepayments, rental_prepayments_detalle, remaining_lease_liability, percent_rent_yn, atributos_extra) VALUES ('4c4621b1-57f7-4691-8aea-0fe95b6d48a8', '2178a0ef-32f6-4f9f-b6db-f3ed3d2ca4d2', '83602737-ca9f-417e-b1ac-19d0ad371be6', 'Plaza Torrecillas Sublease: Tiendas Soriana, S.A. De C.V. (04/08/2022 - 04/07/2032)', NULL, true, 'activo', 'Lease', NULL, '2022-05-01', '2021-11-08', '2032-04-07', '2042-04-07', false, 2, NULL, 2, NULL, NULL, '2032-02-07', 'Send Notice to Renew', 119, 'Tiendas Soriana, S.A. De C.V.', NULL, NULL, '3102 Avenida Alejandro De Rodas', 'A', 'Monterrey', 'MX-NLE', '64610', 'MX', 'Marcela Pérez Olivas', '818-329-9048', NULL, 150, 'percent', NULL, NULL, 1116900, 'EL SUBARRENDATARIO se obliga a pagar a SORIANA, dentro de los 7 días hábiles posteriores a la firma del presente Contrato, 5 (cinco) meses de rentas adelantadas con base a la contraprestación pactada en la cláusula inmediata anterior, lo que equivale a la cantidad total de $1''116,900.00 (un millón ciento dieciséis mil novecientos pesos 00/100M.N)., por concepto de rentas anticipadas, mediante transferencia electrónica al número de cuenta 65506039166 y CLABE INTERBANCARIA número 014580655060391665 del Banco SANTANDER MEXICO S.A INSTITUCION DE BANCA MULTIPLE en Monterrey, Nuevo León a favor de Tiendas Soriana, S.A de C.V.', NULL, false, '{"lease_most_recent_note":"No","see_lease_for_details":"No","lease_is_silent":"No","rtr_enabled":1}'::jsonb);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('4c4621b1-57f7-4691-8aea-0fe95b6d48a8', 'Domicilio del Contrato', E'Av. Municipio Libre y calle Nayarit No 555 Colonia El jardin C.P. 72490, en el municipio de Puebla Puebla\nLocal identificado como Subancla D', 'America Gonzalez', NULL);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('4c4621b1-57f7-4691-8aea-0fe95b6d48a8', 'Fecha de Firma del Contrato', '25 de octubre de 2021', 'America Gonzalez', NULL);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('4c4621b1-57f7-4691-8aea-0fe95b6d48a8', 'Fecha de Apertura', '14 de abril de 2022', 'America Gonzalez', NULL);
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('4c4621b1-57f7-4691-8aea-0fe95b6d48a8', 'Common Area Maintenance Charges', '3', '4', 'CONTRAPRESTACIÓN', E'- The subtenant must pay a maintenance fee equal to 10% of the current monthly rent.\n- This fee starts when the business begins operations in the commercial area.\n- The fee will include the applicable value-added tax (VAT) or any future tax that replaces it.\n- The subtenant will not contribute to the shopping center''s advertising expenses, so no advertising costs will be charged to them.', 'Adicionalmente EL SUBARRENDATARIO deberá cubrir una cuota de mantenimiento equivalente al 10% de la renta mensual actual vigente, dicha cantidad se comenzará a pagar a partir de la apertura o inicio de operaciones del negocio que operará en EL ÁREA COMERCIAL, En el entendido que a dicha cantidad se le agregará el correspondiente impuesto al valor agregado o el impuesto que en su momento llegare a sustituirlo. Las Partes convienen que EL SUBARRENDATARIO no participará en los gastos de Publicidad del Centro Comercial por lo que no se generará cantidad alguno por concepto de publicidad a cargo de éste.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('4c4621b1-57f7-4691-8aea-0fe95b6d48a8', 'Pago de Rentas', '2', '4', 'CONTRAPRESTACIÓN', E'- The monthly payment for the sublease is $223,380.00.\n- Payment is due in advance starting May 1, 2022.\n- This amount is subject to applicable value-added tax (VAT) or any future replacement tax.', 'Las partes contratantes pactan como contraprestación mensual por el Subarrendamiento, pagadera por anticipado a partir del 1°-primero de Mayo del 2022-dos mil veintidós la cantidad de $223,380.00 (doscientos veintitrés mil trescientos ochenta pesos 00/100 MN), más el correspondiente impuesto al valor agregado o el impuesto que en su momento llegare a substituirle...".');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('4c4621b1-57f7-4691-8aea-0fe95b6d48a8', 'Late Fees', '3', '4', 'CONTRAPRESTACIÓN', E'- If payment is late by more than 10 days, late interest will be added to the unpaid balance.\n- The late interest rate is three times the Interbank Equilibrium Interest Rate published by Banxico, spread over the time of delay.\n- If there are unpaid rents or interest, any payment made will first cover the interest, and the remainder will go towards the rent owed.\n- If rent is not paid within the first 10 days of the month, a 4% monthly late interest will be added, spread over the time of delay.\n- Payments will first cover interest, then any remaining amount will go towards the rent owed.', E'A partir del onceavo día se acumularán al saldo insoluto, intereses moratorios, calculados a razón de la tasa anualizada que resulte de multiplicar por 3 (tres) la TASA DE INTERES INTERBANCARIA DE EQUILIBRIO, publicada mensualmente por Banxico, prorrateado durante el tiempo que permanezca en mora; en caso de existir adeudos por rentas o intereses, EL SUBARRENDATARIO reconoce y acepta que cualquier cantidad que abonase se aplicará primero a cubrir los intereses, y en su caso, el restante a cuenta de las rentas adeudadas.\n\nEn caso de que EL SUBARRENDATARIO no realice el pago de la Renta dentro de los primeros diez días naturales del mes que corresponda, sobre el entendido que a partir del décimo primer día se acumularán al saldo insoluto, intereses moratorios, a razón del 4% (cuatro por ciento) mensual, prorrateado durante el tiempo que permanezca en mora; en caso de existir adeudos por rentas o intereses, EL SUBARRENDATARIO reconoce y acepta que cualquier cantidad que abonase se aplicará primero a cubrir los intereses, y en su caso, el restante a cuenta de las rentas adeudadas.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('4c4621b1-57f7-4691-8aea-0fe95b6d48a8', 'Incremento de Renta', '4', '6', 'AUMENTO DE RENTA', E'- The monthly sublease payment for the commercial area will increase annually in January.\n- The first increase will be in January 2023.\n- The increase will match the rise in the National Consumer Price Index published by INEGI or any replacement index for measuring inflation in Mexico.\n- Annual increases cannot exceed 8% of the current payment amount.', 'El importe de la contraprestación mensual por el subarrendamiento de EL ÁREA COMERCIAL se incrementará Anualmente, durante los meses de enero de cada año, siendo el primer incremento hasta el mes de enero del año 2023, en la misma proporción en que aumente el Índice Nacional de Precios al Consumidor que publique el INEGI (o el índice que lo sustituyere para medir la inflación en los Estados Unidos Mexicanos), en la inteligencia de que dichos aumentos anuales no podrán ser mayor a un 8% del valor de la contraprestación vigente que opere en dicho período.');
INSERT INTO locations (id, nombre, brand_id, company_id, address1, address2, city, state, zip, country, full_address, latitude, longitude, location_type, location_subtype, business_category, business_type, property_name, square_meters, total_leased_sqm, total_subleased_sqm, atributos_extra) VALUES ('8e4bbc11-62bc-4bbf-9fb6-fe9efa65bee9', 'Multiplaza Valle Dorado', '43a59b98-494b-4f44-a59a-ad5bb1b79127', '83602737-ca9f-417e-b1ac-19d0ad371be6', '3227 Boulevard Manuel Ávila Camacho', '83A 83B', 'Tlalnepantla De Baz', 'Mexico', '54020', 'MX', '3227 Boulevard Manuel Ávila Camacho, 83A 83B, Tlalnepantla De Baz, Mexico 54020', 19.549766, -99.208795, 'Retail', 'Lifestyle Center', 'Sports & Recreation', 'Franchise', 'Multiplaza Valle Dorado', 2333.09, 2333.09, NULL, '{"map_lease_expiration_date":"2027-12-17","map_marker_color":"#A879D2","coordinate":"rooftop|19.5497660000|-99.2087950000|accurate","city_state":"Tlalnepantla De Baz, Mexico","company_name":"Fitness Para Todos, S. de R.L. de C.V.","location_currency":{"id":"mexican_peso","label":"Mexican peso","symbol":"$","code":"MXN","default":false},"landlord_company_full_address":"26 Boulevard Magnocentro, 5° piso, Huixquilucan, MX-MEX 52787","tenant_company_full_address":"Calzada De Los Leones 170 Piso 1, Alvaro Obregon, CDMX 01010","tenant_company_addr1":"Calzada De Los Leones 170 Piso 1","tenant_company_city":"Alvaro Obregon","tenant_company_state":"CDMX","tenant_company_zip":"01010","tenant_company_country":"MX","lease_currency":{"id":"mexican_peso","label":"Mexican peso","symbol":"$","code":"MXN","default":false},"lease_expiration_date":"2027-12-17","lease_length_in_months_remaining":14,"lease_most_recent_note":"No","see_lease_for_details":"No","lease_is_silent":"No","rtr_enabled":1,"grid_id":57824,"grid_name":"Multiplaza Valle Dorado","grid_full_address":"3227 Boulevard Manuel Ávila Camacho, 83A 83B, Tlalnepantla De Baz, Mexico 54020","map_addr_1":"3227 Boulevard Manuel Ávila Camacho","map_addr_2":"83A 83B","map_city_state_zip":"Tlalnepantla De Baz, Mexico 54020","grid_brand":"Planet Fitness","is_next_percent_rent_payment":"No","location_created_at":"2025-09-29 17:29:37","active_lease_count_over_time":51135,"location_count_over_time":57824,"remaining_rent_liability_over_time":51135}'::jsonb);
INSERT INTO leases (id, location_id, tenant_company_id, lease_name, lease_type, is_sub_lease, estatus, acquisition_type, lease_classification, rent_commencement_date, delivery_date, expiration_date, expiration_date_including_options, is_month_to_month, number_of_options, each_option_years, remaining_options, remaining_options_years, renewal_notice_period_start, renewal_notice_deadline, renewal_notice_intention, length_of_lease_months, landlord_nombre, landlord_parent_company, landlord_vendor_id, landlord_address1, landlord_address2, landlord_city, landlord_state, landlord_zip, landlord_country, landlord_poc_nombre, landlord_poc_telefono, landlord_poc_email, grace_period_dias, late_fee_type, late_fee_monto, security_deposit, rental_prepayments, rental_prepayments_detalle, remaining_lease_liability, percent_rent_yn, atributos_extra) VALUES ('371bcc0e-39aa-424b-9637-5e9f434b95ce', '8e4bbc11-62bc-4bbf-9fb6-fe9efa65bee9', '83602737-ca9f-417e-b1ac-19d0ad371be6', 'Multiplaza Valle Dorado Lease: LMF Frisa Comercial, S. de R.L. de C.V. (03/22/2022 - 12/17/2027)', NULL, false, 'activo', 'Lease', NULL, '2023-03-01', '2022-09-01', '2027-12-17', NULL, false, NULL, NULL, 0, NULL, NULL, NULL, NULL, 68, 'LMF Frisa Comercial, S. de R.L. de C.V.', NULL, NULL, '26 Boulevard Magnocentro', '5° piso', 'Huixquilucan', 'MX-MEX', '52787', 'MX', 'Director de Operaciones', NULL, NULL, 120, 'percent', NULL, 466594.66, 466594.66, 'El Arrendatario se obliga a entregar al Arrendador, dentro de los 60 (sesenta) días naturales siguientes a la fecha de firma del Contrato un monto equivalente a 1 (uno) mes de Renta, más su I.V.A., por concepto de renta anticipada, (la "Renta Anticipada"); en el entendido que el monto de la Renta Anticipada será aplicado por el Arrendador: (i) siempre y cuando el Arrendatario inaugure la negociación que instalará en el Inmueble, a más tardar, en la Fecha de Conclusión del Plazo de Adaptación y finalice en dicha fecha, las obras de adaptación aprobadas en el Proyecto Ejecutivo Definitivo, al pago de las primeras Rentas exigibles, hasta donde alcance, debiendo el Arrendador entregar al Arrendatario una factura por la cantidad correspondiente, la cual deberá reunir todos los requisitos legales que le sean aplicables al momento de su expedición.', NULL, true, '{"lease_most_recent_note":"No","see_lease_for_details":"No","lease_is_silent":"No","rtr_enabled":1,"is_next_percent_rent_payment":"No"}'::jsonb);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('371bcc0e-39aa-424b-9637-5e9f434b95ce', 'Vigencia', E'Hay dos fechas de inicio, de acuerdo a la redacción de la cláusula: La fecha de firma y la fecha de apertura\n\nEl plazo de vigencia del Contrato, iniciará a partir de la fecha de su firma y concluirá una vez que hubieren transcurrido 60 (sesenta) meses, contados a partir del día en que el Arrendatario tiene la obligación de inaugurar la negociación que instalará en el Inmueble, en los términos de la cláusula cuarta; o bien, de la fecha en que efectivamente se realice este evento, lo que ocurra primero, fecha a la que, en lo sucesivo, se le denominará como la "Fecha de Inicio". El plazo de vigencia a que se refiere esta cláusula es forzoso para ambas Partes.', 'America Gonzalez', NULL);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('371bcc0e-39aa-424b-9637-5e9f434b95ce', 'Amendment', E'El Arrendatario se obliga a recibir a su entera satisfacción el Inmueble en la fecha y hora que indique el Arrendador, lo cual deberá ocurrir a más tardar 1 de septiembre de 2022.\n\nEl Arrendador otorga al Arrendatario un plazo de adaptación que concluirá el 28 de febrero de 2023 (la "Fecha de Conclusión del Plazo de Adaptación").', 'America Gonzalez', NULL);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('371bcc0e-39aa-424b-9637-5e9f434b95ce', 'Domicilio del Contrato', E'Boulevard Manuel Ávila Camacho 3,227, Fraccionamiento Valle Dorado, Municipio de Tlalnepantla de Baz, Estado de México, C.P. 54020 \nLocal comercial identificado con los números: 83A, 83B', 'America Gonzalez', NULL);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('371bcc0e-39aa-424b-9637-5e9f434b95ce', 'Fecha de Apertura', '17 de diciembre de 2022', 'America Gonzalez', NULL);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('371bcc0e-39aa-424b-9637-5e9f434b95ce', 'Fecha de Firma del Contrato', '22 de marzo de 2022', 'America Gonzalez', NULL);
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('371bcc0e-39aa-424b-9637-5e9f434b95ce', 'Late Fees', '10', '5', 'INTERESES MORATORIOS', E'- If the Tenant fails to pay the Rent or any other financial obligation under the Contract, including applicable VAT, as specified in the Contract, they must pay late interest if the Landlord requests it.\n- The late interest is calculated from the date of default until the full amount and interest are paid.\n- The interest rate is twice the 28-day Interbank Equilibrium Interest Rate (TIIE) published by the Bank of Mexico.\n- Interest is calculated monthly, even if the delay is only for one day.', 'Para el caso que el Arrendatario no cubra la Renta y/o cualquier otra obligación pecuniaria del Contrato y su respectivo I.V.A, en caso de que el pago del mismo sea aplicable, en la forma y términos estipulados en este Contrato, éste se obliga a pagar al Arrendador, si así éste se lo requiere, un interés moratorio que habrá de ser calculado, a partir de la fecha en que incurra en mora y hasta la fecha en que efectivamente sea pagado el importe del capital y los intereses generados, a la tasa mensual que resulte de multiplicar, por 2 (dos), la Tasa de Interés Interbancaria de Equilibrio (TIIE), a 28 (veintiocho) días, según publicación hecha por el Banco de México, a través de su página de internet, en el entendido que el cómputo de este interés, se hará por períodos mensuales, no obstante que la morosidad corresponda a un solo día.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('371bcc0e-39aa-424b-9637-5e9f434b95ce', 'Percentage Rent', '8', '4', 'RENTA', E'- The "Variable Rent" is 8% of the Monthly Net Sales made by the Tenant on the property.\n- This Variable Rent is combined with the Monthly Minimum Guaranteed Rent to form the total "Rent."', 'La cantidad que resulte de aplicar el 8% (ocho por ciento] a las Ventas Netas Mensuales (según dicho término se define más adelante) que el Arrendatario realice en el Inmueble, a la cual, en lo sucesivo se le denominará como la "Renta Variable" y conjuntamente con la Renta Mínima Mensual De Garantía la "Renta".');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('371bcc0e-39aa-424b-9637-5e9f434b95ce', 'Incremento de Renta', '9', '4 (3)', 'RENTA', E'- The rent will increase every 12 months from the start date.\n- The increase will match the inflation rate from the National Consumer Price Index (INPC) for the past 12 months.\n- The annual rent increase cannot exceed 10%.\n- If inflation exceeds 15%, both parties will meet to decide the rent increase amount.', E'Las Partes acuerdan que la Renta se incrementará cada vez que transcurra un período de 12 (doce) meses contados a partir de la fecha asentada en el acta de inauguración, aplicándose a las Rentas Mensuales pagaderas a partir e incluyendo el mes siguiente a dicho periodo, el 100% (cien por ciento) del porcentaje de la inflación que refleje el Índice Nacional de Precios al Consumidor (en lo sucesivo denominado como "INPC") publicado por el Instituto Nacional de Estadística y Geografía para los 12 (doce) meses anteriores conocidos En la inteligencia de que dichos aumentos anuales no podrán ser mayor a un 10%.\n\nEn caso de que el porcentaje de la inflación que refleje el Índice Nacional de Precios al Consumidor sea mayor al 15%, Las Partes se reunirán para definir el monto del incremento que se deberá de aplicar a la Renta.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('371bcc0e-39aa-424b-9637-5e9f434b95ce', 'Common Area Maintenance Charges', '13', '9 (4)', 'MANTENIMIENTO DEL INMUEBLE', E'- The tenant must pay the landlord a monthly maintenance fee.\n- This fee is 15% of the rent, plus applicable VAT.\n- The maintenance fee is paid in advance each month, along with the rent.\n- The fee is used for maintenance, repairs, and other necessary expenses for the shopping center.\n- The tenant cannot decide on the type of maintenance performed.', 'El Arrendatario se obliga a pagar al Arrendador o a la persona física o moral que designe el Arrendador una cuota de mantenimiento mensual, equivalente al 15 % (quince por ciento) de la Renta, más su correspondiente I.V.A. (la "Cuota de Mantenimiento"), y será pagadera, por mensualidades adelantadas, junto con la Renta del mes que corresponda, en cada Fecha de Pago. La Cuota de Mantenimiento será utilizada para el adecuado mantenimiento, adaptación, reparación y demás gastos que sean necesarios y convenientes para el uso adecuado del Centro Comercial conforme lo establece el Reglamento. El pago de la Cuota de Mantenimiento no da derecho al Arrendatario para determinar o decidir sobre el tipo de mantenimiento que se debe dar en el Centro Comercial, lo cual acepta expresamente a la celebración del Contrato.');
